        const SKIN42_PORTRAIT_URL = "data:image/png;base64,";
        const SKIN42_PORTRAIT_IMG = new Image();
        SKIN42_PORTRAIT_IMG.onload = () => {
            const pCanvas = document.getElementById('profileShipCanvas');
            if (pCanvas && window.__xpace && window.__xpace.getActiveShipConfig().id === 'skin42') {
                window.__xpace.drawShipPreview(pCanvas, window.__xpace.getActiveShipConfig());
            }
            const hangarOverlay = document.getElementById('hangarOverlay');
            if (hangarOverlay && !hangarOverlay.classList.contains('hidden') && window.__xpace && window.__xpace.activeShopTab === 'SHIPS') {
                window.__xpace.renderHangarModal();
            }
        };
        SKIN42_PORTRAIT_IMG.src = SKIN42_PORTRAIT_URL;

        function isSkin42Available() {
            const now = new Date();
            const deadline = new Date(2026, 10, 30, 23, 59, 59); // 30 ноября 2026
            return now.getTime() <= deadline.getTime();
        }

        function getSkin42DaysLeft() {
            const now = new Date();
            const deadline = new Date(2026, 10, 30, 23, 59, 59);
            const diff = deadline.getTime() - now.getTime();
            return Math.max(1, Math.ceil(diff / (1000 * 60 * 60 * 24)));
        }

